'use strict';

// MODULES //

var assertSchema = require( '@data-apis/schema/assert' );
var canonicalBytes = require( '@data-apis/canonical/bytes' );
var sha256 = require( '@data-apis/canonical/sha256' );
var seriesExecutionTarget = require( '@data-apis/execution-target/series' );
var validateExecutionTarget = require( '@data-apis/execution-target/validate' );
var seriesSchema = require( '@data-apis/series-schema' );
var variantSchema = require( '@data-apis/variant-schema' );
var normalizeTimestamp = require( '@data-apis/report/normalize-timestamp' );
var parsePythonSeries = require( '@data-apis/report/parse-python-series' );


// FUNCTIONS //

/**
* Requires a string to be trimmed.
*
* @private
* @param {string} value - value
* @param {string} field - field name
*/
function requireTrimmed( value, field ) {
	if ( value !== value.trim() ) {
		throw new Error( field + ' must not have leading or trailing whitespace' );
	}
}

/**
* Validates summary counts against individual test outcomes.
*
* @private
* @param {Object} report - compliance report
*/
function validateSummary( report ) {
	var summary = report.data.summary;
	var tests = report.data.tests;
	var counts = new Map();
	var declared;

	if ( tests.length !== summary.total ) {
		throw new Error( 'data.tests length ' + tests.length + ' does not equal summary.total ' + summary.total );
	}
	if ( summary.collected < summary.total ) {
		throw new Error( 'summary.collected must be greater than or equal to summary.total' );
	}
	tests.forEach( function countOutcome( test ) {
		requireTrimmed( test.nodeid, 'data.tests[].nodeid' );
		requireTrimmed( test.outcome, 'data.tests[].outcome' );
		counts.set( test.outcome, ( counts.get( test.outcome ) || 0 ) + 1 );
	} );
	declared = Object.entries( summary ).filter( function filterTotals( entry ) {
		return entry[ 0 ] !== 'total' && entry[ 0 ] !== 'collected';
	} ).reduce( function sumOutcomes( sum, entry ) {
		return sum + entry[ 1 ];
	}, 0 );
	if ( declared !== summary.total ) {
		throw new Error( 'Summary outcome counts ' + declared + ' do not equal summary.total ' + summary.total );
	}
	counts.forEach( function compare( count, outcome ) {
		if ( summary[ outcome ] !== count ) {
			throw new Error( 'summary.' + outcome + ' does not match test outcomes' );
		}
	} );
}


// MAIN //

/**
* Validates and derives normalized metadata for a compliance report.
*
* @param {Object} report - compliance report
* @param {Object} [options] - validation options
* @param {string} [options.expectedName] - registered report name
* @param {number} [options.now] - current epoch milliseconds
* @returns {Object} validated report metadata
*/
function validateReport( report, options ) {
	var fields;
	var timestamp;
	var pythonSeries;
	var series;
	var seriesBytes;
	var variant;
	var variantBytes;
	var bytes;
	var normalizedReport;

	options = options || {};
	if ( !report || report.schema !== 'v1' ) {
		throw new Error( 'Unsupported compliance report schema: ' + String( report && report.schema ) );
	}
	assertSchema( 'compliance-v1', report );
	fields = [
		['name', report.name],
		['version', report.version],
		['api_version', report.api_version],
		['python', report.python],
		['platform.description', report.platform.description],
		['platform.system', report.platform.system],
		['platform.release', report.platform.release],
		['platform.machine', report.platform.machine]
	];
	fields.forEach( function validateField( field ) {
		requireTrimmed( field[ 1 ], field[ 0 ] );
	} );
	validateExecutionTarget( report.execution_target );
	if ( options.expectedName && report.name !== options.expectedName ) {
		throw new Error( 'Report name ' + report.name + ' does not match registered name ' + options.expectedName );
	}
	if ( report.data.exitcode !== 0 && report.data.exitcode !== 1 ) {
		throw new Error( 'Unsupported pytest exit code: ' + report.data.exitcode );
	}
	if ( !Number.isFinite( report.data.duration ) ) {
		throw new Error( 'data.duration must be finite' );
	}
	validateSummary( report );
	timestamp = normalizeTimestamp( report.timestamp, options.now );
	pythonSeries = parsePythonSeries( report.python );
	series = {
		'api_version': report.api_version,
		'python': pythonSeries,
		'platform': {
			'system': report.platform.system,
			'machine': report.platform.machine
		},
		'execution_target': seriesExecutionTarget( report.execution_target )
	};
	seriesBytes = canonicalBytes( Object.assign( {
		'series_schema': seriesSchema
	}, series ) );
	variant = {
		'api_version': report.api_version,
		'python': report.python,
		'platform': structuredClone( report.platform ),
		'execution_target': structuredClone( report.execution_target )
	};
	variantBytes = canonicalBytes( Object.assign( {
		'variant_schema': variantSchema
	}, variant ) );
	normalizedReport = structuredClone( report );
	normalizedReport.timestamp = timestamp;
	bytes = canonicalBytes( normalizedReport );
	return {
		'report': normalizedReport,
		'bytes': bytes,
		'reportSha256': sha256( bytes ),
		'timestamp': timestamp,
		'series': series,
		'seriesSchema': seriesSchema,
		'seriesKey': 'sha256:' + sha256( seriesBytes ),
		'variant': variant,
		'variantSchema': variantSchema,
		'variantKey': 'sha256:' + sha256( variantBytes )
	};
}


// EXPORTS //

module.exports = validateReport;
